package com.beatoflove.standardcalculator;
import java.math.*;
import java.util.*;
public final class FinancialMath {
 static final MathContext MC=MathContext.DECIMAL128;
 static final BigDecimal H=new BigDecimal("100"), ONE=BigDecimal.ONE;
 static BigDecimal dec(String s){return new BigDecimal(s.trim().replace(",",""),MC);}
 static BigDecimal pct(BigDecimal n){return n.divide(H,MC);}
 static BigDecimal div(BigDecimal a,BigDecimal b){if(b.signum()==0)throw new IllegalArgumentException("ตัวหารต้องไม่เป็นศูนย์");return a.divide(b,MC);}
 static BigDecimal val(double x){if(!Double.isFinite(x))throw new IllegalArgumentException("ผลลัพธ์อยู่นอกขอบเขต");return BigDecimal.valueOf(x);}
 static double number(BigDecimal x){return x.doubleValue();}
 static void need(boolean x,String msg){if(!x)throw new IllegalArgumentException(msg);}
 static int periods(BigDecimal n){int k=n.intValueExact();need(k>0&&k<=1200,"จำนวนงวด 1–1200");return k;}
 static BigDecimal tax(BigDecimal a,BigDecimal r,boolean inclusive){need(r.signum()>=0,"อัตราต้องไม่ติดลบ");BigDecimal f=ONE.add(pct(r),MC);return inclusive?div(a,f):a.multiply(f,MC);}
 static BigDecimal payment(BigDecimal principal,BigDecimal annual,BigDecimal n){int k=periods(n);double r=number(annual)/1200;need(principal.signum()>=0&&r>=0,"เงินต้นและดอกเบี้ยต้องไม่ติดลบ");return r==0?div(principal,n):val(number(principal)*r/(-Math.expm1(-k*Math.log1p(r))));}
 static BigDecimal npv(BigDecimal rate,BigDecimal[] cf){double r=number(rate)/100;need(r> -1,"อัตราต้องมากกว่า -100%");double sum=0;for(int i=0;i<cf.length;i++)sum+=number(cf[i])/Math.pow(1+r,i);return val(sum);}
 static BigDecimal[] cash(String raw){String[] a=raw.trim().split("[;,\\n\\s]+");need(a.length>=2&&a.length<=1201,"กรอกกระแสเงินสดอย่างน้อย 2 ค่า (คั่นด้วย ;)");BigDecimal[] b=new BigDecimal[a.length];for(int i=0;i<a.length;i++)b[i]=dec(a[i]);return b;}
 static BigDecimal irr(BigDecimal[] cf){int changes=0,last=0;for(BigDecimal c:cf){int s=c.signum();if(s!=0){if(last!=0&&s!=last)changes++;last=s;}}need(changes==1,"IRR ต้องมีกระแสเงินสดเปลี่ยนเครื่องหมายครั้งเดียวในรุ่นนี้");double lo=-99.9,hi=100;double a=number(npv(val(lo),cf)),b=number(npv(val(hi),cf));while(Math.signum(a)==Math.signum(b)&&hi<100000){hi*=2;b=number(npv(val(hi),cf));}need(Math.signum(a)!=Math.signum(b)||a==0||b==0,"ไม่พบ IRR ในช่วงที่รองรับ");if(a==0)return val(lo);if(b==0)return val(hi);for(int i=0;i<100;i++){double m=(lo+hi)/2, v=number(npv(val(m),cf));if(v==0)return val(m);if(Math.signum(v)==Math.signum(a)){lo=m;a=v;}else hi=m;}return val((lo+hi)/2);}
 static String money(BigDecimal x,int scale,RoundingMode mode){return x.setScale(scale,mode).toPlainString();}
 static String f(BigDecimal x){return x.setScale(4,RoundingMode.HALF_UP).stripTrailingZeros().toPlainString();}
 static String calc(String n,String[] v,int mode){if(n.equals("IRR"))return f(irr(cash(v[0])))+"%";if(n.equals("NPV"))return f(npv(dec(v[0]),cash(v[1])));if(n.equals("Payback Period")){BigDecimal[] cf=cash(v[0]);need(cf[0].signum()<0,"Initial outflow must be negative");BigDecimal rem=cf[0].negate();for(int i=1;i<cf.length;i++){if(cf[i].signum()>0&&cf[i].compareTo(rem)>=0)return f(BigDecimal.valueOf(i-1).add(div(rem,cf[i])))+" periods";rem=rem.subtract(cf[i]);}return "Not recovered";}BigDecimal x=dec(v[0]),y=dec(v[1]),z=v.length>2?dec(v[2]):BigDecimal.ZERO;switch(n){case "VAT":BigDecimal incl=tax(x,y,false),net=tax(x,y,true);return "Add VAT: "+f(incl)+"\nVAT: "+f(incl.subtract(x))+"\nRemove VAT: "+f(net);case "Withholding Tax":BigDecimal w=x.multiply(pct(y));return "Tax: "+f(w)+"\nNet paid: "+f(x.subtract(w));case "Profit & Margin":return "Profit: "+f(y.subtract(x))+"\nMargin: "+f(div(y.subtract(x),y).multiply(H))+"%\nMarkup: "+f(div(y.subtract(x),x).multiply(H))+"%";case "ROI":return f(div(y.subtract(x),x).multiply(H))+"%";case "Markup / Markdown":return f(x.multiply(ONE.add(pct(y))).multiply(ONE.subtract(pct(z))));case "Discount":return f(x.multiply(ONE.subtract(pct(y))).multiply(ONE.subtract(pct(z))));case "Break-even":need(y.compareTo(z)>0,"Selling price must exceed variable cost");return div(x,y.subtract(z)).setScale(0,RoundingMode.CEILING)+" units";case "Unit Cost":return f(div(x,y));case "Loan & Installment":case "Amortization":BigDecimal p=payment(x,y,z);StringBuilder sb=new StringBuilder("Monthly: "+f(p)+"\nTotal interest: "+f(p.multiply(z).subtract(x)));if(n.equals("Amortization")){BigDecimal balance=x,r=div(y,new BigDecimal("1200"));for(int i=1;i<=periods(z);i++){BigDecimal interest=balance.multiply(r,MC),principal=p.subtract(interest);balance=balance.subtract(principal);sb.append("\n").append(i).append(": P ").append(f(principal)).append(" / I ").append(f(interest)).append(" / Bal ").append(f(balance));}}return sb.toString();case "Simple Interest":return f(x.multiply(ONE.add(pct(y).multiply(z))));case "Compound Interest":case "Future Value":return f(val(number(x)*Math.pow(1+number(y)/100,number(z))));case "Depreciation":return f(div(x.subtract(y),z))+" / year";case "CAGR":need(x.signum()>0&&y.signum()>0&&z.signum()>0,"Values and years must be positive");return f(val((Math.pow(number(y)/number(x),1/number(z))-1)*100))+"%";case "Time Value of Money":double pv=number(x),fv=number(y),pm=number(z),period=number(dec(v[3])),r=number(dec(v[4]))/100;return f(val(tvm(pv,fv,pm,period,r,mode)));default:throw new IllegalArgumentException("Unknown tool");}}
 static double factor(double r,double n){return r==0?n:Math.expm1(n*Math.log1p(r))/r;}
 static double tvm(double pv,double fv,double p,double n,double r,int mode){need(r>-1&&n>=0,"Invalid rate or period");double g=Math.pow(1+r,n),a=factor(r,n);switch(mode){case 0:return -(pv*g+p*a);case 1:return -(fv+p*a)/g;case 2:return -(fv+pv*g)/a;case 3:return r==0?-(pv+fv)/p:Math.log((p-r*fv)/(p+r*pv))/Math.log1p(r);default:double lo=-.99,hi=10,fl=pv*Math.pow(1+lo,n)+p*factor(lo,n)+fv,fh=pv*Math.pow(1+hi,n)+p*factor(hi,n)+fv;need(Math.signum(fl)!=Math.signum(fh),"No unique bracketed rate");for(int i=0;i<100;i++){double mid=(lo+hi)/2, fm=pv*Math.pow(1+mid,n)+p*factor(mid,n)+fv;if(Math.signum(fm)==Math.signum(fl))lo=mid;else hi=mid;}return (lo+hi)*50;}}
}
